DROP DATABASE IF EXISTS sql101;

CREATE DATABASE sql101;

DROP DATABASE IF EXISTS retail;

CREATE SCHEMA retail;

DROP DATABASE IF EXISTS software;

CREATE SCHEMA software;

DROP DATABASE IF EXISTS example;

CREATE SCHEMA example;

CREATE TABLE software.plans
(
   plan_id      integer,
   plan_type    varchar(20),
   plan_length  integer,
   price        integer
);

CREATE TABLE retail.inventory
(
   inventory_id     integer,
   product_id       integer,
   created_at       timestamp,
   last_updated_at  timestamp,
   total_on_hand    integer,
   total_on_order   integer
);

CREATE TABLE retail.orders
(
   order_id         integer,
   customer_id      integer,
   completed_at     timestamp,
   order_qty        integer,
   promotion_id     integer,
   total            numeric(12,2),
   discount_amount  numeric(12,2),
   tax_amount       numeric(12,2),
   final_total      numeric(12,2),
   payment_id       integer,
   refund_id        integer
);

CREATE TABLE retail.products
(
   product_id      integer,
   product_code    varchar(20),
   product_type    varchar(255),
   color           varchar(255),
   size            numeric(12,1),
   full_name       varchar(255),
   category        varchar(255),
   material        varchar(255),
   created_at      date,
   original_price  integer,
   current_price   integer,
   on_markdown     boolean
);

CREATE TABLE example.products
(
   product_id      integer,
   product_code    varchar(20),
   product_type    varchar(255),
   color           varchar(255),
   size            numeric(12,1),
   full_name       varchar(255),
   category        varchar(255),
   material        varchar(255),
   created_at      date,
   original_price  integer,
   current_price   integer,
   on_markdown     boolean
);





